{"code":"# Use fetch API with credentials to send the request from the browser
fetch_result = js("""
(async () => {
    try {
        const response = await fetch('http://192.168.64.2:8080/WebGoat/HttpBasics/external', {
            method: 'PUT',
            headers: {
                'User-Agent': 'Attacker',
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({external: true}),
            credentials: 'include'
        });
        const text = await response.text();
        return text.substring(0, 200);
    } catch (e) {
        return e.message.substring(0, 200);
    }
})()
""")
